layers.vertex:
attribute vec3 aO; attribute float aT, aK, aC; uniform float uTime; varying vec2 vP; varying float vU, vK, vC;
    void main(){
      // kinds: 0 collision flash · 1 landing ring · 2 stance-accent ground pulse (fast, thin) · 3 Tank second ring (firm impact)
      float u = uTime - aT, life = aK < .5 ? .16 : (aK < 1.5 ? .3 : (aK < 2.5 ? .24 : .32));
      if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK; vC = aC;
      bool bb = aK < .5 || aK > 1.5;                               // payoff pulses sit on the body at the collision point, not on the ground
      if (bb){
        vec4 mv = viewMatrix*vec4(aO,1.); mv.xyz += normalize(-mv.xyz)*.35;
        float S = aK < .5 ? .38 : (aK < 2.5 ? .5 : .4); mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv;
      } else {
        float S = aK < 1.5 ? .5 : (aK < 2.5 ? .95 : .75); vP = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .035, -position.y*S), 1.);
      }
    }

layers.fragment:
uniform vec3 uGold, uOrange, uCW, uCT; varying vec2 vP; varying float vU, vK, vC; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec2 p = vP; float r = length(p), lum = 0., hot = 0.;
      if (vK > 1.5){
        // II payoff: one instant pulse in the stance accent (Warrior magenta / Tank cyan)
        float T = vK < 2.5 ? .24 : .32, t = vU/T, f = pow(1. - t, 1.7);
        float R = vK < 2.5 ? .15 + .72*(1. - pow(1. - t, 3.)) : .1 + .55*(1. - pow(1. - t, 5.));
        float w = (vK < 2.5 ? .018 : .035)*(1. - .5*t);
        float ring = exp(-pow(abs(r - R)/w, 2.4)), core = lcore(r - R, w*.35);
        vec3 col = mix(uCW, uCT, vC);
        vec3 outc = (col*ring*(vK < 2.5 ? 1. : .8) + mix(col, vec3(1.), .6)*core*.5)*f;
        if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
        gl_FragColor = vec4(outc, 1.); return;
      }
      if (vK < .5){
        // single collision flash: a crisp ring that snaps open + a hot centre, gone in 160 ms
        float t = vU/.16, f = pow(1. - t, 1.6);
        float R = .04 + .25*(1. - pow(1. - t, 3.)), w = .007 + .01*(1. - t);
        lum += exp(-pow(abs(r - R)/w, 2.4))*f*.8 + exp(-r*r*240.)*(vU < .033 ? 1.2 : .5*f);
        hot += lcore(r - R, w*.35)*f*.45 + exp(-r*r*700.)*f*.6;
      } else {
        // landing ring on the floor: thin, compact, settles quickly
        float t = vU/.3, f = pow(1. - t, 1.8);
        float R = .08 + .35*(1. - pow(1. - t, 3.)), w = .006 + .015*(1. - t);
        lum += exp(-pow(abs(r - R)/w, 2.4))*f*.5; hot += lcore(r - R, w*.3)*f*.25;
      }
      vec3 outc = mix(uOrange, uGold, .6)*lum + mix(uGold, vec3(1., .96, .88), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
